import { Readable } from 'node:stream';
async function main(): Promise<void> {
  const r: any = new Readable({ read() {} });
  setTimeout(() => { r.push('a'); r.push(null); }, 20);
  // the Promise settles only after the AOT timer above fires, with the AOT frame suspended on it
  const out: any = await r.toArray();
  console.log(out.length, String(out[0]));
  let ticks = 0;
  const t = setInterval(() => { ticks++; }, 5);
  const r2: any = new Readable({ read() {} });
  setTimeout(() => { r2.push('b'); r2.push(null); }, 40);
  const out2: any = await r2.toArray();
  clearInterval(t);
  console.log(String(out2[0]), ticks >= 3);
}
